@pytest.mark.asyncio async def test_failed_device_close_preserves_old_worker_for_retry() -> None: device, table, device_type, point_table_id = _device()
# One transient close failure across the whole factory: the replacement # worker's later close (and process stop) must succeed. failure_budget = {"remaining": 1}
class CloseFailsOnceDriver(FakeDriver): def __init__(self) -> None: super().__init__() self.closes = 0
async def close(self) -> None: self.closes += 1 if failure_budget["remaining"]: failure_budget["remaining"] -= 1 raise RuntimeError("device close failed") await super().close()
created: list[CloseFailsOnceDriver] = []
